function renderPlanControls() { const date = planViewDate(); const mode = planMode(date); const input = el("plan-date"); if (input) input.value = date; el("plan-mode-select").value = mode; el("plan-mode-title").textContent = `${planModeLabel(mode)} · 第 ${teachingWeek(date) || "预览"} 教学周`; el("plan-mode-copy").textContent = mode === "normal" ? `自动匹配 ${formatDate(date)} 的周循环任务。` : mode === "rest" ? `${formatDate(date)} 使用全休日模板。` : `本教学周使用${planModeLabel(mode)}模板。`; const formal = isFormalDate(date); el("execution-mode").textContent = formal ? "执行模式" : "预览模式"; el("execution-mode").classList.toggle("is-formal", formal); el("tasks-title").textContent = formal && date === today() ? "把今天走完" : `预览 ${formatDate(date)}`; }
