function renderWeekDays() { const host=el("week-days"); const start=weekStart(new Date(`${scheduleDate()}T12:00:00`)); const date=new Date(`${start}T12:00:00`); host.replaceChildren(...Array.from({length:7},(_,index)=>{const d=new Date(date);d.setDate(date.getDate()+index);const value=d.toISOString().slice(0,10);const button=document.createElement("button");button.type="button";button.className=`week-day${value===scheduleDate()?" is-active":""}${value===today()?" is-today":""}`;button.innerHTML=`<span>${["日","一","二","三","四","五","六"][d.getDay()]}</span><strong>${String(d.getDate()).padStart(2,"0")}</strong>`;button.addEventListener("click",()=>{state.ui.scheduleDate=value;saveState();renderSchedule();});return button;})); }
function renderSchedule() { const date=scheduleDate(); el("schedule-date-title").textContent=`${formatDate(date)} · 07:00 - 23:30`; const items=scheduleItems(date); const list=el("schedule-list"); list.replaceChildren(...items.map((item,index)=>{const article=document.createElement("article");article.className=`schedule-item schedule-${item.type}${item.rigid?" is-rigid":" is-flexible"}${item.done?" is-done":""}`;article.draggable=!item.rigid;article.dataset.scheduleId=item.id;const custom=!item.rigid&&!String(item.id).startsWith("schedule-");article.innerHTML=`<div class="schedule-time"><strong>${item.start}</strong><span>${item.end}</span></div><div class="schedule-body"><div class="schedule-title-row"><h3>${esc(item.title)}</h3><span class="schedule-tag">${scheduleTypeLabel(item.type)}</span></div><p>${esc(item.detail)}</p></div><div class="schedule-item-actions"><label class="schedule-check" title="标记完成"><input type="checkbox" ${item.done?"checked":""} aria-label="完成 ${esc(item.title)}"><span></span></label>${custom?`<button type="button" class="schedule-delete" aria-label="删除${esc(item.title)}">×</button>`:""}</div>`;article.title=item.detail;article.querySelector("input").addEventListener("change",event=>toggleScheduleDone(item,event.target.checked));article.addEventListener("dblclick",()=>item.rigid?showToast("刚性课程不可编辑"):openScheduleEditor(item));article.querySelector(".schedule-delete")?.addEventListener("click",event=>{event.stopPropagation();deleteScheduleItem(item);});if(!item.rigid){article.addEventListener("dragstart",event=>event.dataTransfer.setData("text/plain",item.id));article.addEventListener("dragover",event=>event.preventDefault());article.addEventListener("drop",event=>{event.preventDefault();moveSchedule(event.dataTransfer.getData("text/plain"),item.id);});}return article;})); const done=items.filter(item=>item.done).length;el("schedule-completion").textContent=`完成率 ${items.length?Math.round(done/items.length*100):0}%`;renderWeekDays();renderWeeklyProgress();const note=state.dailyNotes[date]||"";el("daily-note").value=note; }
