function moveSchedule(sourceId,targetId){const source=scheduleItems().find(item=>item.id===sourceId);const target=scheduleItems().find(item=>item.id===targetId);if(!source||!target||source.rigid||target.rigid)return;const key=source.id.replace(`schedule-${source.date}-`,"");state.scheduleOverrides[source.date]=state.scheduleOverrides[source.date]||[];state.scheduleOverrides[source.date]=state.scheduleOverrides[source.date].filter(item=>item.id!==source.id);state.scheduleOverrides[source.date].push({...source,start:target.start,end:target.end});saveState();renderSchedule();showToast("弹性事项时间已调整");}
