function loadPlan(date, mode) { state.ui.planDate = date || defaultPlanDate(); const weekly = ["experiment", "exam"].includes(mode); const dates = weekly || mode === "normal" ? weekDates(state.ui.planDate) : [state.ui.planDate]; if (weekly) { state.specialWeeks[planWeekKey(state.ui.planDate)] = mode; } else if (mode === "normal") { delete state.specialWeeks[planWeekKey(state.ui.planDate)]; delete state.specialDays[state.ui.planDate]; } else { state.specialDays[state.ui.planDate] = mode; } state.tasks = state.tasks.filter(task => !(dates.includes(task.date) && String(task.source || "").startsWith("内置模板:"))); dates.forEach(item => ensurePlanTasks(item, planMode(item))); saveState(); renderAll(); showToast(`${weekly ? "本教学周" : formatDate(state.ui.planDate)} · ${planModeLabel(planMode(state.ui.planDate))} 已加载`); }
function parseClock(text) { const m=String(text||"").match(/(?:^|\s)([01]?\d|2[0-3])[:：]([0-5]\d)/); if(m) return `${String(Number(m[1])).padStart(2,"0")}:${m[2]}`; if(/上午/.test(text)) return "08:30"; if(/下午/.test(text)) return "14:00"; if(/晚上|晚间|傍晚/.test(text)) return "19:30"; return ""; }
