function guessCategory(text, fallback="生活") { if(/数竞|竞赛|高数|数学|线代|概率/.test(text))return /数竞|竞赛/.test(text)?"数竞":"数学"; if(/英语|单词|阅读|作文|长难句/.test(text))return "英语"; if(/材料力学|应力|弯曲|扭转|内力/.test(text))return "材料力学"; if(/健身|力量|跑步|有氧|训练|拉伸/.test(text))return "训练"; if(/课程|上课|作业|实验|课堂/.test(text))return "课内"; return fallback; }
function guessTool(text, category) { if(/手机.*(?:网课|视频)|网课.*手机/.test(text)&&/平板|MatePad|刷题/.test(text))return "手机看网课 + MatePad刷题"; if(/平板|MatePad|刷题|PDF|讲义/.test(text))return "MatePad + 纸笔"; if(/手机|网课|视频|B站/.test(text))return "手机/电脑看网课"; if(/纸质|试卷|真题|卷子/.test(text))return "纸质卷 + 红笔"; if(["训练","健身"].includes(category))return "健身房 + 手机记录"; if(category==="校园跑")return "校园跑路线 + 手机记录"; return category==="英语"?"手机词汇 App + MatePad":"纸笔/平板"; }
