function normalizeTask(input, defaults={}) { const title=String(input.title||input.task||input.name||"").trim(); if(!title)return null; const category=input.category||guessCategory(title,defaults.category||"生活"); const rawTime=input.time||input.startTime||""; return { id:input.id||id(), title, category, date:input.date||resolveWeekday(input.dayHint||title,defaults.date||today()), startTime:parseClock(rawTime||title), minutes:Number(input.minutes||durationFromRange(rawTime)||guessMinutes(title))||50, tool:input.tool||guessTool(title,category), method:input.method||guessMethod(title,category), output:input.output||guessOutput(title,category), priority:Number(input.priority)||2, done:input.done===true||input.status==="已完成", completedAt:input.completedAt||null, source:input.source||defaults.source||"导入计划" }; }

