function renderFocus(){el("focus-minutes").value=state.settings.focusMinutes;el("break-minutes").value=state.settings.breakMinutes;el("noise-toggle").checked=state.settings.whiteNoise;el("focus-task-select").disabled=Boolean(timer.handle);updateTimer();const history=state.focusSessions.slice(-8).reverse();el("focus-history").replaceChildren(...(history.length?history.map(s=>{const a=document.createElement("article");a.className="history-item";a.innerHTML=`<strong>${esc(state.tasks.find(t=>t.id===s.taskId)?.title||"未关联任务")}</strong><small>${esc(s.date)} · ${s.minutes} 分钟</small>`;return a;}):[empty("完成一次专注后会出现在这里。")]));}
function updateTimer(){const m=String(Math.floor(timer.remaining/60)).padStart(2,"0"),s=String(timer.remaining%60).padStart(2,"0");el("focus-clock").textContent=`${m}:${s}`;el("focus-start").disabled=Boolean(timer.handle);el("focus-pause").disabled=!timer.handle;el("focus-status").textContent=timer.handle?"专注中":timer.mode==="break"?"休息中":"待开始";}
function beginTimer(){if(timer.handle)return;timer.taskId=el("focus-task-select").value;timer.startedAt=Date.now();if(state.settings.whiteNoise&&timer.mode==="focus")startNoise();timer.handle=setInterval(()=>{timer.remaining-=1;if(timer.remaining<=0)finishTimer();updateTimer();},1000);updateTimer();renderFocus();}
function pauseTimer(){clearInterval(timer.handle);timer.handle=null;stopNoise();updateTimer();}
function resetTimer(){clearInterval(timer.handle);timer.handle=null;stopNoise();timer.mode="focus";timer.remaining=Number(state.settings.focusMinutes)*60;el("focus-task-select").disabled=false;updateTimer();renderFocus();}
function finishTimer(){const completedMode=timer.mode;const elapsed=Math.max(1,Math.round((Number(completedMode==="focus"?state.settings.focusMinutes:state.settings.breakMinutes)*60-timer.remaining)/60));clearInterval(timer.handle);timer.handle=null;stopNoise();if(completedMode==="focus"&&elapsed){state.focusSessions.push({id:id(),date:today(),taskId:timer.taskId,minutes:elapsed});if(timer.taskId){const task=state.tasks.find(t=>t.id===timer.taskId);if(task)task.actualMinutes=(task.actualMinutes||0)+elapsed;}saveState();showToast(`已记录 ${elapsed} 分钟专注`);}timer.remaining=completedMode==="focus"?Number(state.settings.breakMinutes)*60:Number(state.settings.focusMinutes)*60;timer.mode=completedMode==="focus"?"break":"focus";el("focus-task-select").disabled=false;updateTimer();renderAll();}
function startNoise(){try{if(noise.context)return;noise.context=new AudioContext();noise.gain=noise.context.createGain();noise.gain.gain.value=.035;const buffer=noise.context.createBuffer(1,noise.context.sampleRate*2,noise.context.sampleRate);const data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;noise.source=noise.context.createBufferSource();noise.source.buffer=buffer;noise.source.loop=true;noise.source.connect(noise.gain).connect(noise.context.destination);noise.source.start();}catch{showToast("当前浏览器无法播放白噪音，专注仍会继续。");}}
function stopNoise(){try{noise.source?.stop();noise.context?.close();}catch{}noise={context:null,source:null,gain:null};}

