async function requestWakeLock(){try{if("wakeLock" in navigator)wakeLock=await navigator.wakeLock.request("screen");}catch{wakeLock=null;}}
function releaseWakeLock(){wakeLock?.release?.().catch?.(()=>{});wakeLock=null;}
function notifyUser(title,body){if("Notification" in window&&Notification.permission==="granted")new Notification(title,{body,icon:"icon.svg"});}
function renderFocus(){el("focus-minutes").value=state.settings.focusMinutes;el("break-minutes").value=state.settings.breakMinutes;el("noise-toggle").checked=state.settings.whiteNoise;el("noise-type").value=state.settings.noiseType||"white";el("noise-volume").value=state.settings.noiseVolume??0.035;el("focus-task-select").disabled=Boolean(timer.handle);updateTimer();const history=state.focusSessions.slice(-8).reverse();el("focus-history").replaceChildren(...(history.length?history.map(s=>{const a=document.createElement("article");a.className="history-item";a.innerHTML=`<strong>${esc(state.tasks.find(t=>t.id===s.taskId)?.title||"未关联任务")}</strong><small>${esc(s.date)} · ${s.minutes} 分钟</small>`;return a;}):[empty("完成一次专注后会出现在这里。 ")]));}
function beginTimer(){if(timer.handle)return;timer.taskId=el("focus-task-select").value;timer.startedAt=Date.now();requestWakeLock();if(state.settings.whiteNoise&&timer.mode==="focus")startNoise();timer.handle=setInterval(()=>{timer.remaining-=1;if(timer.remaining<=0)finishTimer();updateTimer();},1000);updateTimer();renderFocus();}
function pauseTimer(){clearInterval(timer.handle);timer.handle=null;releaseWakeLock();stopNoise();updateTimer();}
function resetTimer(){clearInterval(timer.handle);timer.handle=null;releaseWakeLock();stopNoise();timer.mode="focus";timer.remaining=Number(state.settings.focusMinutes)*60;el("focus-task-select").disabled=false;updateTimer();renderFocus();}
function finishTimer(){const completedMode=timer.mode;const elapsed=Math.max(1,Math.round((Number(completedMode==="focus"?state.settings.focusMinutes:state.settings.breakMinutes)*60-timer.remaining)/60));clearInterval(timer.handle);timer.handle=null;releaseWakeLock();stopNoise();if(completedMode==="focus"&&elapsed){state.focusSessions.push({id:id(),date:today(),taskId:timer.taskId,minutes:elapsed});if(timer.taskId){const task=state.tasks.find(t=>t.id===timer.taskId);if(task)task.actualMinutes=(task.actualMinutes||0)+elapsed;}saveState();showToast(`已记录 ${elapsed} 分钟专注`);notifyUser("专注完成",`已记录 ${elapsed} 分钟专注，休息 ${state.settings.breakMinutes} 分钟。`);}else notifyUser("休息结束","可以开始下一轮专注了。");timer.remaining=completedMode==="focus"?Number(state.settings.breakMinutes)*60:Number(state.settings.focusMinutes)*60;timer.mode=completedMode==="focus"?"break":"focus";el("focus-task-select").disabled=false;updateTimer();renderAll();}
function startNoise(){try{if(noise.context)return;noise.context=new AudioContext();noise.gain=noise.context.createGain();noise.gain.gain.value=Number(state.settings.noiseVolume??0.035);const buffer=noise.context.createBuffer(1,noise.context.sampleRate*2,noise.context.sampleRate);const data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;noise.source=noise.context.createBufferSource();noise.source.buffer=buffer;noise.source.loop=true;let output=noise.source;if(state.settings.noiseType==="rain"){const filter=noise.context.createBiquadFilter();filter.type="lowpass";filter.frequency.value=1400;output.connect(filter);output=filter;}output.connect(noise.gain).connect(noise.context.destination);noise.source.start();}catch{showToast("当前浏览器无法播放声音，专注仍会继续。 ");}}

function renderRun(){const total=state.runs.reduce((s,r)=>s+Number(r.km),0),goal=Number(state.meta.goalKm);el("run-progress-km").textContent=`${total.toFixed(1)} / ${goal} km`;el("run-progress-bar").style.width=`${Math.min(100,total/goal*100)}%`;el("run-remaining").textContent=`还剩 ${Math.max(0,goal-total).toFixed(1)} km`;const week=weekStart();const count=state.runs.filter(r=>r.date>=week).length;el("run-week-count").textContent=`${count} / 5`;el("run-history").replaceChildren(...(state.runs.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,12).map(r=>{const a=document.createElement("article");a.className="history-item";a.innerHTML=`<strong>${r.km} km</strong><small>${esc(r.date)} · ${esc(r.note||"校园跑")}</small>`;return a;})));el("run-km").value=3;}
function renderGym(){el("gym-form-title").textContent=`${currentSplit}日训练`;const presets={"推":["杠铃卧推","哑铃肩推","上斜哑铃卧推","绳索下压"],"拉":["高位下拉","坐姿划船","哑铃弯举","面拉"],"腿":["深蹲/腿举","罗马尼亚硬拉","保加利亚分腿蹲","提踵"]};const list=el("exercise-list");if(!list.children.length||list.dataset.split!==currentSplit){list.dataset.split=currentSplit;list.replaceChildren(...presets[currentSplit].map(name=>exerciseRow(name)));}const bySplit={"推":0,"拉":0,"腿":0};state.workouts.forEach(w=>bySplit[w.split]+=1);el("gym-progress").replaceChildren(...Object.entries(bySplit).map(([split,count])=>{const a=document.createElement("div");a.className="gym-progress-item";a.innerHTML=`<span>${split}</span><div class="mini-track"><i style="width:${Math.min(100,count/8*100)}%"></i></div><b>${count}</b>`;return a;}));el("gym-history").replaceChildren(...(state.workouts.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8).map(w=>{const a=document.createElement("article");a.className="history-item";a.innerHTML=`<strong>${esc(w.split)}日 · ${w.exercises.length} 个动作</strong><small>${esc(w.date)} · ${esc(w.note||"无备注")}</small>`;return a;})));}
function exerciseRow(name="") {const row=document.createElement("div");row.className="exercise-row";row.innerHTML=`<label>动作<input class="exercise-name" value="${esc(name)}" placeholder="动作名称"></label><label>组数<input class="exercise-sets" type="number" min="1" max="20" value="3"></label><label>重量<input class="exercise-weight" type="number" min="0" step="0.5" value="0"></label><button type="button" class="remove-exercise" aria-label="删除动作">×</button>`;row.querySelector(".remove-exercise").addEventListener("click",()=>row.remove());return row;}

function renderStats(){const period=el("stats-period").value;const dates=datesForPeriod(period);const set=new Set(dates);const tasks=state.tasks.filter(t=>set.has(t.date));const study=state.focusSessions.filter(s=>set.has(s.date)).reduce((s,x)=>s+Number(x.minutes),0);const runs=state.runs.filter(r=>set.has(r.date)).reduce((s,x)=>s+Number(x.km),0);const gyms=state.workouts.filter(w=>set.has(w.date)).length;el("stats-learning").textContent=study;el("stats-completion").textContent=`${tasks.length?Math.round(tasks.filter(t=>t.done).length/tasks.length*100):0}%`;el("stats-run").textContent=runs.toFixed(1);el("stats-gym").textContent=gyms;drawCharts(dates);const subject={};tasks.forEach(t=>{subject[t.category]=(subject[t.category]||0)+1;});const total=tasks.length;el("subject-breakdown").replaceChildren(...(Object.entries(subject).sort((a,b)=>b[1]-a[1]).map(([name,count])=>{const row=document.createElement("div");row.className="subject-row";row.innerHTML=`<span>${esc(name)}</span><div class="mini-track"><i style="width:${total?count/total*100:0}%;background:${categoryColor(name)}"></i></div><small>${count} 项</small>`;return row;})) );}
function drawCharts(dates){const learn=dates.map(d=>learningMinutes(d));const run=dates.map(d=>state.runs.filter(r=>r.date===d).reduce((s,r)=>s+Number(r.km),0));const gym=dates.map(d=>state.workouts.filter(w=>w.date===d).length);drawChart(el("learning-chart"),dates,[learn],["#0f766e"],"学习分钟");drawChart(el("activity-chart"),dates,[run,gym],["#176b9c","#b45309"],"跑步公里 / 健身次数");}
function drawChart(canvas,labels,series,colors,title){const ctx=canvas.getContext("2d");const width=canvas.clientWidth||760;const height=canvas.clientHeight||300;const dpr=window.devicePixelRatio||1;canvas.width=width*dpr;canvas.height=height*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,width,height);const pad={l:38,r:16,t:18,b:34};const innerW=width-pad.l-pad.r,innerH=height-pad.t-pad.b;const max=Math.max(1,...series.flat());ctx.strokeStyle="#d9e1de";ctx.fillStyle="#61706d";ctx.font="11px system-ui";for(let i=0;i<=4;i++){const y=pad.t+innerH*i/4;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(width-pad.r,y);ctx.stroke();ctx.fillText(String(Math.round(max*(4-i)/4)),4,y+4);}const step=labels.length>1?innerW/(labels.length-1):innerW;series.forEach((values,si)=>{ctx.strokeStyle=colors[si];ctx.fillStyle=colors[si];ctx.lineWidth=2;ctx.beginPath();values.forEach((v,i)=>{const x=pad.l+step*i,y=pad.t+innerH-(v/max)*innerH;i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();values.forEach((v,i)=>{const x=pad.l+step*i,y=pad.t+innerH-(v/max)*innerH;ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();});});ctx.fillStyle="#61706d";const stride=Math.max(1,Math.ceil(labels.length/7));labels.forEach((label,i)=>{if(i%stride===0)ctx.fillText(label.slice(5),pad.l+step*i-12,height-10);});}

