function showView(view){currentView=view;document.querySelectorAll(".nav-button").forEach(b=>b.classList.toggle("is-active",b.dataset.view===view));document.querySelectorAll(".view").forEach(v=>v.classList.toggle("is-visible",v.id===`${view}-view`));if(view==="stats")setTimeout(renderStats,0);}

function parseCsvLine(line){const cells=[];let cell="",quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'&&line[i+1]==='"'){cell+='"';i++;continue}if(c==='"'){quoted=!quoted;continue}if((c===","||c==="\t")&&!quoted){cells.push(cell.trim());cell="";continue}cell+=c;}cells.push(cell.trim());return cells;}
function parsePlanRows(rows,defaults={}){return rows.map(row=>normalizeTask({title:row.任务||row.task||row.title||row.名称||row.name||"",category:row.类别||row.category,date:row.日期||row.date,dayHint:row.星期||row["星期/情境"]||row.weekday,time:row.时间||row.time||row.开始时间||row.starttime,minutes:row.分钟||row.minutes||row.预计分钟||row.计划分钟,tool:row.工具||row.tool||row.tools||row["工具/方法"],method:row.方法||row.method||row.怎么做,output:row.产出||row.output||row.结果||row.result||row.预期产出,priority:row.优先级||row.priority,status:row.状态||row.status},defaults)).filter(Boolean);}
function parseText(text,defaults={}){const clean=text.replace(/\r/g,"").trim();if(!clean)return[];try{const parsed=JSON.parse(clean);const rows=Array.isArray(parsed)?parsed:parsed.tasks;if(Array.isArray(rows))return rows.map(r=>normalizeTask(r,defaults)).filter(Boolean);}catch{}const lines=clean.split("\n").map(x=>x.trim()).filter(Boolean);if(lines.length>1&&lines[0].split(/[,\t]/).length>=2){const headers=parseCsvLine(lines[0]).map(x=>x.toLowerCase());return parsePlanRows(lines.slice(1).map(line=>Object.fromEntries(headers.map((h,i)=>[h,parseCsvLine(line)[i]||""]))),defaults);}return lines.map(line=>normalizeTask({title:line.replace(/^[-*•\d.、)]+\s*/,"")},defaults)).filter(Boolean);}
async function loadXlsx(file,defaults){if(!window.XLSX)await loadScript("https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js");const wb=window.XLSX.read(await file.arrayBuffer(),{type:"array"});for(const name of wb.SheetNames){const matrix=window.XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,defval:""});const hi=matrix.slice(0,20).findIndex(row=>row.some(c=>["任务","task","title","名称","name"].includes(String(c).trim().toLowerCase())));if(hi<0)continue;const headers=matrix[hi].map(c=>String(c).trim());const rows=matrix.slice(hi+1).filter(r=>r.some(c=>String(c).trim()));const tasks=parsePlanRows(rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]??""]))),{...defaults,source:`Excel-${name}`});if(tasks.length)return tasks;}throw Error("没有找到任务表头");}
async function loadScript(src){await new Promise((resolve,reject)=>{const s=document.createElement("script");s.src=src;s.onload=resolve;s.onerror=()=>reject(Error("解析器加载失败"));document.head.append(s);});}
async function readImport(file,defaults){if(/\.xlsx$/i.test(file.name))return loadXlsx(file,defaults);if(/\.docx$/i.test(file.name)){if(!window.mammoth)await loadScript("https://unpkg.com/mammoth@1.8.0/mammoth.browser.min.js");return parseText((await window.mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()})).value,defaults);}if(/\.pdf$/i.test(file.name)){const pdf=await import("https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs");pdf.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs";const doc=await pdf.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;let text="";for(let i=1;i<=doc.numPages;i++){const page=await doc.getPage(i);const c=await page.getTextContent();text+=c.items.map(x=>x.str).join(" ")+"\n";}return parseText(text,defaults);}return parseText(await file.text(),defaults);}
function renderImportPreview(){const node=el("import-preview");node.replaceChildren(...(importDrafts.length?importDrafts.map((t,i)=>{const a=document.createElement("article");a.className="import-preview-card";a.innerHTML=`<strong>${i+1}. ${esc(t.title)}</strong><small>${esc(t.date)} ${esc(t.startTime||"待排")} · ${esc(t.category)} · ${t.minutes} 分钟<br>${esc(t.tool)}<br>${esc(t.method)}<br>产出：${esc(t.output)}</small>`;return a;}):[empty("识别结果会显示在这里，确认前不会写入计划。 ")]));el("confirm-import").disabled=!importDrafts.length;}

