function installFocusEnhancements(){document.querySelectorAll("[data-focus-preset]").forEach(button=>button.addEventListener("click",()=>{const presets={math:[45,10],english:[30,5],general:[25,5]};const [focus,rest]=presets[button.dataset.focusPreset];state.settings.focusMinutes=focus;state.settings.breakMinutes=rest;timer.mode="focus";timer.remaining=focus*60;saveState();renderFocus();showToast(`${button.textContent} 已应用`);}));el("noise-type").addEventListener("change",()=>{state.settings.noiseType=el("noise-type").value;saveState();if(timer.handle&&state.settings.whiteNoise){stopNoise();startNoise();}});el("noise-volume").addEventListener("input",()=>{state.settings.noiseVolume=Number(el("noise-volume").value);if(noise.gain)noise.gain.gain.value=state.settings.noiseVolume;saveState();});el("notify-enable").addEventListener("click",async()=>{if(!("Notification" in window)){showToast("当前浏览器不支持通知");return}const permission=await Notification.requestPermission();showToast(permission==="granted"?"浏览器提醒已开启":"未开启浏览器提醒");});}

