function renderStats(){const period=el("stats-period").value;const dates=datesForPeriod(period);const set=new Set(dates);const tasks=state.tasks.filter(t=>set.has(t.date)&&isFormalDate(t.date));const study=state.focusSessions.filter(s=>set.has(s.date)&&isFormalDate(s.date)).reduce((s,x)=>s+Number(x.minutes),0);const runs=state.runs.filter(r=>set.has(r.date)&&isFormalDate(r.date)).reduce((s,x)=>s+Number(x.km),0);const gyms=state.workouts.filter(w=>set.has(w.date)&&isFormalDate(w.date)).length;el("stats-learning").textContent=study;el("stats-completion").textContent=`${tasks.length?Math.round(tasks.filter(t=>t.done).length/tasks.length*100):0}%`;el("stats-run").textContent=runs.toFixed(1);el("stats-gym").textContent=gyms;const latest=state.weights.slice().sort((a,b)=>b.date.localeCompare(a.date))[0];el("stats-weight").textContent=latest?Number(latest.value).toFixed(1):"--";drawCharts(dates);const subject={};tasks.forEach(t=>{subject[t.category]=(subject[t.category]||0)+1;});const total=tasks.length;el("subject-breakdown").replaceChildren(...(Object.entries(subject).sort((a,b)=>b[1]-a[1]).map(([name,count])=>{const row=document.createElement("div");row.className="subject-row";row.innerHTML=`<span>${esc(name)}</span><div class="mini-track"><i style="width:${total?count/total*100:0}%;background:${categoryColor(name)}"></i></div><small>${count} 项</small>`;return row;})) );}
