function showView(view){currentView=view;document.querySelectorAll(".nav-button").forEach(b=>b.classList.toggle("is-active",b.dataset.view===view));document.querySelectorAll(".view").forEach(v=>v.classList.toggle("is-visible",v.id===`${view}-view`));if(view==="stats")setTimeout(()=>{renderStats();chartInstances.forEach(chart=>chart.resize());},0);}

function exerciseRow(name=""){const row=document.createElement("div");row.className="exercise-row";row.innerHTML=`<label>动作<input class="exercise-name" value="${esc(name)}" placeholder="动作名称"></label><label>组数<input class="exercise-sets" type="number" min="1" max="20" value="3"></label><label>次数<input class="exercise-reps" type="number" min="1" max="100" value="8"></label><label>重量<input class="exercise-weight" type="number" min="0" step="0.5" value="0"></label><button type="button" class="remove-exercise" aria-label="删除动作">×</button>`;row.querySelector(".remove-exercise").addEventListener("click",()=>row.remove());return row;}
function renderGym(){el("gym-form-title").textContent=`${currentSplit}日训练`;const presets={"推":["杠铃卧推","哑铃肩推","上斜哑铃卧推","绳索下压"],"拉":["高位下拉","坐姿划船","哑铃弯举","面拉"],"腿":["深蹲/腿举","罗马尼亚硬拉","保加利亚分腿蹲","提踵"],"核心":["平板支撑","悬垂举腿","死虫","侧桥"]};const list=el("exercise-list");if(!list.children.length||list.dataset.split!==currentSplit){list.dataset.split=currentSplit;list.replaceChildren(...presets[currentSplit].map(name=>exerciseRow(name)));}const bySplit={"推":0,"拉":0,"腿":0,"核心":0};state.workouts.forEach(w=>{if(bySplit[w.split]!==undefined)bySplit[w.split]+=1;});el("gym-progress").replaceChildren(...Object.entries(bySplit).map(([split,count])=>{const a=document.createElement("div");a.className="gym-progress-item";a.innerHTML=`<span>${split}</span><div class="mini-track"><i style="width:${Math.min(100,count/8*100)}%"></i></div><b>${count}</b>`;return a;}));el("gym-history").replaceChildren(...(state.workouts.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8).map(w=>{const a=document.createElement("article");a.className="history-item";a.innerHTML=`<strong>${esc(w.split)}日 · ${w.exercises.length} 个动作</strong><small>${esc(w.date)} · ${esc(w.note||"无备注")}</small>`;return a;})));}
function installGymCapture(){el("gym-form").addEventListener("submit",event=>{event.preventDefault();event.stopImmediatePropagation();const exercises=[...document.querySelectorAll(".exercise-row")].map(row=>({name:row.querySelector(".exercise-name").value.trim(),sets:Number(row.querySelector(".exercise-sets").value),reps:Number(row.querySelector(".exercise-reps").value),weight:Number(row.querySelector(".exercise-weight").value)})).filter(item=>item.name);if(!exercises.length){showToast("至少记录一个动作");return}state.workouts.push({id:id(),date:el("gym-date").value,split:currentSplit,exercises,note:el("gym-note").value.trim()});saveState();el("gym-note").value="";el("exercise-list").replaceChildren();showToast("训练已保存");renderAll();},true);}

function drawEcharts(id,labels,series,colors,kind){if(!window.echarts)return false;const canvas=el(id);const host=canvas.parentElement.querySelector(`[data-echarts-host="${id}"]`)||document.createElement("div");if(!host.parentElement){host.dataset.echartsHost=id;host.className="echarts-host";canvas.hidden=true;canvas.parentElement.append(host);}let chart=chartInstances.get(id);if(!chart){chart=window.echarts.init(host);chartInstances.set(id,chart);}chart.setOption({animation:false,grid:{left:42,right:18,top:20,bottom:34},tooltip:{trigger:"axis"},xAxis:{type:"category",data:labels.map(label=>label.slice(5)),axisLabel:{color:"#61706d"}},yAxis:{type:"value",axisLabel:{color:"#61706d"},splitLine:{lineStyle:{color:"#d9e1de"}}},series:series.map((data,index)=>({name:kind[index]||kind[0],type:index===0&&kind[0]==="学习分钟"?"bar":"line",smooth:true,data,itemStyle:{color:colors[index]},lineStyle:{color:colors[index]},barMaxWidth:24}))},true);return true;}
function drawCharts(dates){const learn=dates.map(d=>learningMinutes(d));const run=dates.map(d=>state.runs.filter(r=>r.date===d).reduce((s,r)=>s+Number(r.km),0));const gym=dates.map(d=>state.workouts.filter(w=>w.date===d).length);const weight=dates.map(d=>{const entry=state.weights.find(item=>item.date===d);return entry?Number(entry.value):null;});if(!drawEcharts("learning-chart",dates,[learn],["#0f766e"],["学习分钟"]))drawChart(el("learning-chart"),dates,[learn],["#0f766e"],"学习分钟");if(!drawEcharts("activity-chart",dates,[run,gym],["#176b9c","#b45309"],["校园跑公里","健身次数"]))drawChart(el("activity-chart"),dates,[run,gym],["#176b9c","#b45309"],"跑步公里 / 健身次数");if(!drawEcharts("weight-chart",dates,[weight],["#7c3aed"],["体重 kg"]))drawChart(el("weight-chart"),dates,[weight],["#7c3aed"],"体重 kg");}
function drawSubjectPie(subject){if(!window.echarts)return;const canvas=el("subject-chart");const host=canvas.parentElement.querySelector('[data-echarts-host="subject-chart"]')||document.createElement("div");if(!host.parentElement){host.dataset.echartsHost="subject-chart";host.className="echarts-host";canvas.hidden=true;canvas.parentElement.insertBefore(host,el("subject-breakdown"));}let chart=chartInstances.get("subject-chart");if(!chart){chart=window.echarts.init(host);chartInstances.set("subject-chart",chart);}chart.setOption({animation:false,tooltip:{trigger:"item"},legend:{bottom:0,textStyle:{color:"#61706d"}},series:[{type:"pie",radius:["35%","68%"],data:Object.entries(subject).map(([name,value])=>({name,value}),),label:{color:"#17211f"}}]},true);}
function renderStats(){const period=el("stats-period").value;const dates=datesForPeriod(period);const set=new Set(dates);const tasks=state.tasks.filter(t=>set.has(t.date)&&isFormalDate(t.date));const study=state.focusSessions.filter(s=>set.has(s.date)&&isFormalDate(s.date)).reduce((s,x)=>s+Number(x.minutes),0);const runs=state.runs.filter(r=>set.has(r.date)&&isFormalDate(r.date)).reduce((s,x)=>s+Number(x.km),0);const gyms=state.workouts.filter(w=>set.has(w.date)&&isFormalDate(w.date)).length;el("stats-learning").textContent=study;el("stats-completion").textContent=`${tasks.length?Math.round(tasks.filter(t=>t.done).length/tasks.length*100):0}%`;el("stats-run").textContent=runs.toFixed(1);el("stats-gym").textContent=gyms;const latest=state.weights.slice().sort((a,b)=>b.date.localeCompare(a.date))[0];el("stats-weight").textContent=latest?Number(latest.value).toFixed(1):"--";drawCharts(dates);const subject={};tasks.forEach(t=>{subject[t.category]=(subject[t.category]||0)+1;});drawSubjectPie(subject);const total=tasks.length;el("subject-breakdown").replaceChildren(...(Object.entries(subject).sort((a,b)=>b[1]-a[1]).map(([name,count])=>{const row=document.createElement("div");row.className="subject-row";row.innerHTML=`<span>${esc(name)}</span><div class="mini-track"><i style="width:${total?count/total*100:0}%;background:${categoryColor(name)}"></i></div><small>${count} 项</small>`;return row;})) );}

function renderMonthlyTargetStatus(){const cards=document.querySelector("#stats-view .stats-cards");if(!cards)return;let card=document.getElementById("stats-target-card");if(!card){card=document.createElement("article");card.id="stats-target-card";card.className="summary-card";card.innerHTML='<span>月度目标</span><strong id="stats-target-status">--</strong><small id="stats-target-copy">学习 / 跑步 / 健身</small>';cards.append(card);}const now=new Date();const year=now.getFullYear();const month=String(now.getMonth()+1).padStart(2,"0");const prefix=`${year}-${month}`;const targets=state.meta.monthlyTargets||DEFAULT_STATE.meta.monthlyTargets;const study=state.focusSessions.filter(item=>String(item.date).startsWith(prefix)).reduce((sum,item)=>sum+Number(item.minutes||0),0);const run=state.runs.filter(item=>String(item.date).startsWith(prefix)).reduce((sum,item)=>sum+Number(item.km||0),0);const gym=state.workouts.filter(item=>String(item.date).startsWith(prefix)).length;const ratios=[study/targets.studyMinutes,run/targets.runKm,gym/targets.gymSessions];const progress=Math.min(...ratios);const status=progress>=1?"已达标":progress>=0.7?"按计划":"需追回";document.getElementById("stats-target-status").textContent=status;document.getElementById("stats-target-copy").textContent=`学习 ${study}/${targets.studyMinutes} · 跑步 ${run.toFixed(1)}/${targets.runKm} · 健身 ${gym}/${targets.gymSessions}`;}
function renderStats(){const period=el("stats-period").value;const dates=datesForPeriod(period);const set=new Set(dates);const tasks=state.tasks.filter(t=>set.has(t.date)&&isFormalDate(t.date));const study=state.focusSessions.filter(s=>set.has(s.date)&&isFormalDate(s.date)).reduce((s,x)=>s+Number(x.minutes),0);const runs=state.runs.filter(r=>set.has(r.date)&&isFormalDate(r.date)).reduce((s,x)=>s+Number(x.km),0);const gyms=state.workouts.filter(w=>set.has(w.date)&&isFormalDate(w.date)).length;el("stats-learning").textContent=study;el("stats-completion").textContent=`${tasks.length?Math.round(tasks.filter(t=>t.done).length/tasks.length*100):0}%`;el("stats-run").textContent=runs.toFixed(1);el("stats-gym").textContent=gyms;const latest=state.weights.slice().sort((a,b)=>b.date.localeCompare(a.date))[0];el("stats-weight").textContent=latest?Number(latest.value).toFixed(1):"--";drawCharts(dates);const subject={};tasks.forEach(t=>{subject[t.category]=(subject[t.category]||0)+1;});drawSubjectPie(subject);const total=tasks.length;el("subject-breakdown").replaceChildren(...(Object.entries(subject).sort((a,b)=>b[1]-a[1]).map(([name,count])=>{const row=document.createElement("div");row.className="subject-row";row.innerHTML=`<span>${esc(name)}</span><div class="mini-track"><i style="width:${total?count/total*100:0}%;background:${categoryColor(name)}"></i></div><small>${count} 项</small>`;return row;})) );renderMonthlyTargetStatus();}

function updateTimer(){const m=String(Math.floor(timer.remaining/60)).padStart(2,"0"),s=String(timer.remaining%60).padStart(2,"0");el("focus-clock").textContent=`${m}:${s}`;el("focus-start").disabled=Boolean(timer.handle);el("focus-pause").disabled=!timer.handle;el("focus-finish").disabled=!(timer.startedAt&&timer.mode==="focus");el("focus-status").textContent=timer.handle?"专注中":timer.mode==="break"?"休息中":timer.startedAt?"已暂停":"待开始";}
function recordFocusSession(minutes){if(!minutes)return;const task=state.tasks.find(item=>item.id===timer.taskId);state.focusSessions.push({id:id(),date:today(),taskId:timer.taskId,category:task?.category||"未分类",minutes,endedAt:Date.now()});if(task)task.actualMinutes=(task.actualMinutes||0)+minutes;saveState();}
function finishTimer(){const completedMode=timer.mode;const planned=Number(completedMode==="focus"?state.settings.focusMinutes:state.settings.breakMinutes);const elapsed=Math.max(1,Math.round((planned*60-timer.remaining)/60));clearInterval(timer.handle);timer.handle=null;releaseWakeLock();stopNoise();if(completedMode==="focus"){recordFocusSession(elapsed);showToast(`已记录 ${elapsed} 分钟专注`);notifyUser("专注完成",`已记录 ${elapsed} 分钟专注，休息 ${state.settings.breakMinutes} 分钟。`);}else notifyUser("休息结束","可以开始下一轮专注了。");timer.remaining=completedMode==="focus"?Number(state.settings.breakMinutes)*60:Number(state.settings.focusMinutes)*60;timer.mode=completedMode==="focus"?"break":"focus";timer.startedAt=null;el("focus-task-select").disabled=false;updateTimer();renderAll();}
function finishFocusManually(){if(!timer.startedAt||timer.mode!=="focus")return;const planned=Number(state.settings.focusMinutes);const elapsed=Math.max(1,Math.round((planned*60-timer.remaining)/60));clearInterval(timer.handle);timer.handle=null;releaseWakeLock();stopNoise();recordFocusSession(elapsed);timer.remaining=planned*60;timer.mode="focus";timer.startedAt=null;el("focus-task-select").disabled=false;showToast(`已结束并记录 ${elapsed} 分钟专注`);renderAll();}
function installFocusFinishHandler(){el("focus-finish").addEventListener("click",finishFocusManually);}
function renderRun(){const total=state.runs.reduce((s,r)=>s+Number(r.km),0),goal=Number(state.meta.goalKm);el("run-progress-km").textContent=`${total.toFixed(1)} / ${goal} km`;el("run-progress-bar").style.width=`${Math.min(100,total/goal*100)}%`;el("run-remaining").textContent=`还剩 ${Math.max(0,goal-total).toFixed(1)} km`;const week=weekStart();const count=state.runs.filter(r=>r.date>=week).length;el("run-week-count").textContent=`${count} / 5`;el("run-week-remaining").textContent=`本周还可计入 ${Math.max(0,5-count)} 次；每次最多 3 km。`;el("run-history").replaceChildren(...(state.runs.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,12).map(r=>{const a=document.createElement("article");a.className="history-item";a.innerHTML=`<strong>${r.km} km</strong><small>${esc(r.date)} · ${esc(r.note||"校园跑")}</small>`;return a;})));el("run-km").value=3;}
function renderGym(){el("gym-form-title").textContent=`${currentSplit}日训练`;const presets={"推":["杠铃卧推","哑铃肩推","上斜哑铃卧推","绳索下压"],"拉":["高位下拉","坐姿划船","哑铃弯举","面拉"],"腿":["深蹲/腿举","罗马尼亚硬拉","保加利亚分腿蹲","提踵"],"核心":["平板支撑","悬垂举腿","死虫","侧桥"]};const list=el("exercise-list");if(!list.children.length||list.dataset.split!==currentSplit){list.dataset.split=currentSplit;list.replaceChildren(...presets[currentSplit].map(name=>exerciseRow(name)));}const bySplit={"推":0,"拉":0,"腿":0,"核心":0};state.workouts.forEach(w=>{if(bySplit[w.split]!==undefined)bySplit[w.split]+=1;});el("gym-progress").replaceChildren(...Object.entries(bySplit).map(([split,count])=>{const a=document.createElement("div");a.className="gym-progress-item";a.innerHTML=`<span>${split}</span><div class="mini-track"><i style="width:${Math.min(100,count/8*100)}%"></i></div><b>${count}</b>`;return a;}));el("gym-history").replaceChildren(...(state.workouts.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8).map(w=>{const a=document.createElement("article");a.className="history-item";a.innerHTML=`<strong>${esc(w.split)}日 · ${w.exercises.length} 个动作</strong><small>${esc(w.date)} · ${Number(w.minutes||0)||"未填"} 分钟 · ${esc(w.note||"无备注")}</small>`;return a;})));}
function installGymCapture(){el("gym-form").addEventListener("submit",event=>{event.preventDefault();event.stopImmediatePropagation();const exercises=[...document.querySelectorAll(".exercise-row")].map(row=>({name:row.querySelector(".exercise-name").value.trim(),sets:Number(row.querySelector(".exercise-sets").value),reps:Number(row.querySelector(".exercise-reps").value),weight:Number(row.querySelector(".exercise-weight").value)})).filter(item=>item.name);if(!exercises.length){showToast("至少记录一个动作");return}state.workouts.push({id:id(),date:el("gym-date").value,split:currentSplit,minutes:Number(el("gym-minutes").value),exercises,note:el("gym-note").value.trim()});saveState();el("gym-note").value="";el("exercise-list").replaceChildren();showToast("训练已保存");renderAll();},true);}
function renderStats(){const period=el("stats-period").value;const dates=datesForPeriod(period);const set=new Set(dates);const tasks=state.tasks.filter(t=>set.has(t.date)&&isFormalDate(t.date));const sessions=state.focusSessions.filter(item=>set.has(item.date)&&isFormalDate(item.date));const study=sessions.reduce((sum,item)=>sum+Number(item.minutes||0),0);const runs=state.runs.filter(r=>set.has(r.date)&&isFormalDate(r.date)).reduce((s,x)=>s+Number(x.km),0);const gyms=state.workouts.filter(w=>set.has(w.date)&&isFormalDate(w.date)).length;el("stats-learning").textContent=study;el("stats-completion").textContent=`${tasks.length?Math.round(tasks.filter(t=>t.done).length/tasks.length*100):0}%`;el("stats-run").textContent=runs.toFixed(1);el("stats-gym").textContent=gyms;const latest=state.weights.slice().sort((a,b)=>b.date.localeCompare(a.date))[0];el("stats-weight").textContent=latest?Number(latest.value).toFixed(1):"--";drawCharts(dates);const subject={};sessions.forEach(item=>{const category=item.category||state.tasks.find(task=>task.id===item.taskId)?.category||"未分类";subject[category]=(subject[category]||0)+Number(item.minutes||0);});drawSubjectPie(subject);const total=study;el("subject-breakdown").replaceChildren(...(Object.entries(subject).sort((a,b)=>b[1]-a[1]).map(([name,minutes])=>{const row=document.createElement("div");row.className="subject-row";row.innerHTML=`<span>${esc(name)}</span><div class="mini-track"><i style="width:${total?minutes/total*100:0}%;background:${categoryColor(name)}"></i></div><small>${minutes} 分</small>`;return row;})) );renderMonthlyTargetStatus();}

function renderSchedule(){const selected=scheduleDate();const items=scheduleItems(selected);const list=el("schedule-list");list.className="schedule-list schedule-agenda";el("schedule-date-title").textContent="今天的安排 · "+formatDate(selected);list.replaceChildren(...items.map(item=>{const article=document.createElement("article");article.className="schedule-item schedule-"+item.type+(item.rigid?" is-rigid":" is-flexible")+(item.done?" is-done":"");article.draggable=!item.rigid;article.dataset.scheduleId=item.id;const custom=!item.rigid&&!String(item.id).startsWith("schedule-");article.innerHTML='<div class="schedule-card-time">'+item.start+' - '+item.end+'</div><div class="schedule-body"><div class="schedule-title-row"><h3>'+esc(item.title)+'</h3><span class="schedule-tag">'+scheduleTypeLabel(item.type)+'</span></div><p>'+esc(item.detail)+'</p></div><div class="schedule-item-actions"><label class="schedule-check" title="标记完成"><input type="checkbox" '+(item.done?"checked":"")+' aria-label="完成 '+esc(item.title)+'"><span></span></label>'+(custom?'<button type="button" class="schedule-delete" aria-label="删除'+esc(item.title)+'">×</button>':"")+'</div>';article.title=item.detail;article.querySelector("input").addEventListener("change",event=>toggleScheduleDone(item,event.target.checked));article.addEventListener("dblclick",()=>item.rigid?showToast("刚性课程不可编辑"):openScheduleEditor(item));article.querySelector(".schedule-delete")?.addEventListener("click",event=>{event.stopPropagation();deleteScheduleItem(item);});if(!item.rigid){article.addEventListener("dragstart",event=>event.dataTransfer.setData("text/plain",item.id));article.addEventListener("dragover",event=>event.preventDefault());article.addEventListener("drop",event=>{event.preventDefault();moveSchedule(event.dataTransfer.getData("text/plain"),item.id);});}return article;}));const done=items.filter(item=>item.done).length;el("schedule-completion").textContent="完成率 "+(items.length?Math.round(done/items.length*100):0)+"%";renderWeekDays();renderWeeklyProgress();el("daily-note").value=state.dailyNotes[selected]||"";renderMobileDayHero();}
window.YIJISHU_APP={getState:()=>state,replaceState:next=>{state={...DEFAULT_STATE,...next,settings:{...DEFAULT_STATE.settings,...(next.settings||{})},meta:{...DEFAULT_STATE.meta,...(next.meta||{})},ui:{...DEFAULT_STATE.ui,...(next.ui||{})},specialDays:{...(next.specialDays||{})},specialWeeks:{...(next.specialWeeks||{})},scheduleOverrides:{...(next.scheduleOverrides||{})},dailyNotes:{...(next.dailyNotes||{})},tasks:Array.isArray(next.tasks)?next.tasks:[],focusSessions:Array.isArray(next.focusSessions)?next.focusSessions:[],runs:Array.isArray(next.runs)?next.runs:[],workouts:Array.isArray(next.workouts)?next.workouts:[],weights:Array.isArray(next.weights)?next.weights:[]};saveState();renderAll();},saveState,renderAll,showToast};
Object.assign(window.YIJISHU_APP,{scheduleItems,scheduleTypeLabel,formatDate,weekStart,weekDates,toggleScheduleDone,showView,showToast});
installTaskEditCapture();installFocusEnhancements();installFocusFinishHandler();installWeightHandlers();installGymCapture();installScheduleHandlers();renderAll();bind();if("serviceWorker" in navigator)navigator.serviceWorker.register("service-worker.js?v=18");
